+type retryNativeProvider struct {
+	mu          sync.Mutex
+	mode        string
+	requests    []map[string]any
+	hold        chan struct{}
+	entered     chan struct{}
+	enteredOnce sync.Once
+}
+
+func (p *retryNativeProvider) set(mode string) {
+	p.mu.Lock()
+	defer p.mu.Unlock()
+	p.mode = mode
+	p.requests = nil
+	p.hold = make(chan struct{})
+	p.entered = make(chan struct{})
+	p.enteredOnce = sync.Once{}
