+		provider.mu.Lock()
+		release := provider.hold
+		provider.mu.Unlock()
+		close(release)
+		if state.LatestTurnID == manual.TurnID {
+			retryNativeWait(t, ctx, client, thread, manual.TurnID, "completed")
+		}
+	})
+}
