+			case "cold":
+				f.state = "notLoaded"
+			case "stale":
+				f.turn = "newer"
+			case "queue":
+				f.queued = true
+			case "new active turn race":
+				f.race = true
+			case "unknown":
+				f.unknown = true
+			}
+			client := newTestClient(serveUnixWebsocket(t, f.serve))
+			defer client.Close()
+			if name == "other unresolved send" {
+				if err := client.PrepareSend("thread-1", "other", "other", "other", false); err != nil {
